package store

import (
	"github.com/uptrace/bun"
)

// Ids are generated by the database (see docs/db.md). Fields marked
// scanonly come from joins, for the API.

type Sensor struct {
	bun.BaseModel `bun:"table:sensors,alias:sn"`

	ID        int64  `bun:"id,pk,autoincrement" json:"-"`
	Name      string `bun:"name" json:"id"` // the sensor id of the protocol
	FirstSeen *Time  `bun:"first_seen" json:"first_seen"`
	LastSeen  *Time  `bun:"last_seen" json:"last_seen"`
}

type IngestToken struct {
	bun.BaseModel `bun:"table:ingest_tokens,alias:tok"`

	ID         int64  `bun:"id,pk,autoincrement"`
	SensorID   int64  `bun:"sensor_id"`
	Sensor     string `bun:"sensor,scanonly"`
	Name       string `bun:"name"`
	TokenHash  string `bun:"token_hash"`
	CreatedAt  Time   `bun:"created_at"`
	LastUsedAt *Time  `bun:"last_used_at"`
	RevokedAt  *Time  `bun:"revoked_at"`
}

type TTYFile struct {
	bun.BaseModel `bun:"table:tty_files,alias:t"`

	ID       int64  `bun:"id,pk,autoincrement"`
	SHA256   string `bun:"sha256"`
	Size     int64  `bun:"size"`
	Path     string `bun:"path"`
	StoredAt Time   `bun:"stored_at"`
}

type Session struct {
	bun.BaseModel `bun:"table:sessions,alias:s"`

	ID             int64    `bun:"id,pk,autoincrement" json:"id"`
	SensorID       int64    `bun:"sensor_id" json:"-"`
	Sensor         string   `bun:"sensor,scanonly" json:"sensor"`
	CowrieSession  string   `bun:"cowrie_session" json:"session"`
	SrcIP          *string  `bun:"src_ip" json:"src_ip"`
	SrcPort        *int     `bun:"src_port" json:"src_port"`
	DstIP          *string  `bun:"dst_ip" json:"dst_ip"`
	DstPort        *int     `bun:"dst_port" json:"dst_port"`
	Protocol       *string  `bun:"protocol" json:"protocol"`
	ClientVersion  *string  `bun:"client_version" json:"client_version"`
	HASSH          *string  `bun:"hassh" json:"hassh"`
	StartedAt      Time     `bun:"started_at" json:"started_at"`
	EndedAt        *Time    `bun:"ended_at" json:"ended_at"`
	DurationMS     *int64   `bun:"duration_ms" json:"duration_ms"`
	LoginSuccess   bool     `bun:"login_success" json:"login_success"`
	GeoCountry     *string  `bun:"geo_country" json:"geo_country"` // ISO 3166-1 alpha-2
	GeoCity        *string  `bun:"geo_city" json:"geo_city"`
	GeoSource      *string  `bun:"geo_source" json:"geo_source"` // database used, set even if not found
	GeoLat         *float64 `bun:"geo_lat" json:"geo_lat"`       // of the city, from the same database
	GeoLon         *float64 `bun:"geo_lon" json:"geo_lon"`
	ASN            *int64   `bun:"asn" json:"asn"`         // autonomous system, from the ASN database
	ASOrg          *string  `bun:"as_org" json:"as_org"`   // its organisation
	Verdict        *string  `bun:"verdict" json:"verdict"` // see package verdict; nil until judged
	VerdictScore   *int     `bun:"verdict_score" json:"verdict_score"`
	VerdictVersion *string  `bun:"verdict_version" json:"-"`
}

// SessionRecording is a TTY recording of a session: Cowrie writes one per
// SSH channel, and many bots run each command on its own exec channel.
type SessionRecording struct {
	bun.BaseModel `bun:"table:session_recordings,alias:r"`

	ID        int64 `bun:"id,pk,autoincrement" json:"-"`
	SessionID int64 `bun:"session_id" json:"-"`
	// TTYLog is Cowrie's name for the recording: the SHA-256 of its input,
	// the keys typed or the command of an exec channel.
	TTYLog     string `bun:"ttylog" json:"ttylog"`
	StartedAt  Time   `bun:"started_at" json:"started_at"` // the channel's, in this session
	DurationMS *int64 `bun:"duration_ms" json:"duration_ms"`
	// Duplicate: Cowrie already had a recording of this input and kept its
	// file, with its output and times, maybe of another session.
	Duplicate bool    `bun:"duplicate" json:"duplicate"`
	TTYFileID *int64  `bun:"tty_file_id" json:"-"`          // nil until uploaded
	SHA256    *string `bun:"sha256,scanonly" json:"sha256"` // of the stored file
	Size      *int64  `bun:"size,scanonly" json:"size"`
}

type Event struct {
	bun.BaseModel `bun:"table:events,alias:e"`

	ID         int64  `bun:"id,pk,autoincrement"`
	Hash       []byte `bun:"hash"`
	SensorID   int64  `bun:"sensor_id"`
	SessionID  *int64 `bun:"session_id"`
	Type       string `bun:"column:type"`
	TS         Time   `bun:"ts"`
	ReceivedAt Time   `bun:"received_at"`
}

type EventData struct {
	bun.BaseModel `bun:"table:event_data,alias:ed"`

	EventID int64  `bun:"event_id,pk"`
	Data    string `bun:"data"`
}

type LoginAttempt struct {
	bun.BaseModel `bun:"table:login_attempts,alias:la"`

	ID        int64  `bun:"id,pk,autoincrement" json:"id"`
	SessionID int64  `bun:"session_id" json:"session_id"`
	TS        Time   `bun:"ts" json:"ts"`
	Username  string `bun:"username" json:"username"`
	Password  string `bun:"password" json:"password"`
	Success   bool   `bun:"success" json:"success"`
}

type Command struct {
	bun.BaseModel `bun:"table:commands,alias:c"`

	ID        int64  `bun:"id,pk,autoincrement" json:"id"`
	SessionID int64  `bun:"session_id" json:"session_id"`
	TS        Time   `bun:"ts" json:"ts"`
	Input     string `bun:"input" json:"input"`
}

// Transfer directions.
const (
	Download = "download"
	Upload   = "upload"
)

type Transfer struct {
	bun.BaseModel `bun:"table:transfers,alias:x"`

	ID        int64   `bun:"id,pk,autoincrement" json:"id"`
	SessionID int64   `bun:"session_id" json:"session_id"`
	TS        Time    `bun:"ts" json:"ts"`
	Direction string  `bun:"direction" json:"direction"`
	URL       *string `bun:"url" json:"url"`
	Filename  *string `bun:"filename" json:"filename"`
	SHA256    *string `bun:"sha256" json:"sha256"`
}
